import {createDatabase,sql} from '/app/apps/backend/dist/database.js';import {loadConfig} from '/app/apps/backend/dist/config.js';
const c=loadConfig(process.env);if(c.nodeEnv!=='qa')throw Error('QA_ONLY');const db=createDatabase(c);
try{console.log(JSON.stringify(await db.transaction().execute(async tx=>{await sql`SET TRANSACTION READ ONLY`.execute(tx);
const applicabilities=(await sql`SELECT retention_policy_applicability_id::text AS id,tenant_id::text,retention_policy_id::text,
version_number,classification,scope_subject_id::text,created_by_user_identity_id::text,source_evidence_version_id::text,
source_clause_ref,lifecycle_state,published_at,effective_from,row_version FROM privacy.retention_policy_applicabilities ORDER BY created_at`.execute(tx)).rows;
const audits=(await sql`SELECT aggregate_id::text,event_code,command_code,outcome,actor_user_identity_id::text,actor_service_principal_id::text,
 occurred_at,after_payload->>'lifecycle_state' AS lifecycle_state,after_payload->>'row_version' AS row_version
FROM ops_audit.audit_events WHERE aggregate_type='RetentionPolicyApplicability' ORDER BY occurred_at`.execute(tx)).rows;
const idempotency=(await sql`SELECT operation_code,result_status_code,result_ref FROM ops_audit.idempotency_records
WHERE operation_code LIKE 'retentionApplicability%' ORDER BY created_at`.execute(tx)).rows;
const historical_source=(await sql`SELECT evidence_version_id::text,effective_from,row_version,lifecycle_state FROM evidence.evidence_versions
 WHERE evidence_version_id='01a118e4-ba56-76e7-aa44-d03594933d9c'`.execute(tx)).rows;
const holds=(await sql`SELECT count(*)::int AS releases FROM privacy.retention_policy_hold_releases`.execute(tx)).rows;
return {recorded_at_utc:new Date().toISOString(),scope:'AUTOMATED_QA_TECHNICAL_PENDING_RECORDS_NOT_LEGAL_EVIDENCE_NOT_HUMAN_REVIEW',applicabilities,audits,idempotency,historical_source,holds,transaction:'READ_ONLY'};
})));}finally{await db.destroy();}
